UPDATE DORMITORIES
	SET MAX_COUNT = #{maxCount}
WHERE DORMITORY_ID = #{dormitoryId}

    	UPDATE DORMITORIES
			SET CURRENT_COUNT = CURRENT_COUNT + 1
		WHERE DORMITORY_ID = #{dormitoryId}

    	UPDATE DORMITORIES
			SET CURRENT_COUNT = CURRENT_COUNT - 1
		WHERE DORMITORY_ID = #{dormitoryId}
